import type { AppConfig } from "awatif/templates";

// A single-storey steel portal frame in the XZ work plane: 6 m span, 3 m to
// the eaves, rigid beam-column connections and fixed bases
export const portalFrame: AppConfig = {
  points: [
    [0, 0, 0], // 1 base left
    [0, 0, 3], // 2 eaves left
    [6, 0, 3], // 3 eaves right
    [6, 0, 0], // 4 base right
  ],
  lines: [
    [1, 2], // left column
    [2, 3], // beam
    [3, 4], // right column
  ],

  gridLines: [
    {
      name: "Frame Grid",
      templateId: "grid-system",
      geometry: [],
      params: {
        x: [
          { id: "A", ordinate: 0, visible: true, bubble: "end" },
          { id: "B", ordinate: 3, visible: true, bubble: "end" }, // line of symmetry
          { id: "C", ordinate: 6, visible: true, bubble: "end" },
        ],
        y: [{ id: "1", ordinate: 0, visible: true, bubble: "start" }],
        z: [
          { id: "Base", ordinate: 0, visible: true, bubble: "end" },
          { id: "Eaves", ordinate: 3, visible: true, bubble: "end" },
        ],
      },
    },
  ],

  supports: [
    {
      name: "Fixed Bases",
      templateId: "point-support",
      geometry: [1, 4],
      params: { type: "fixed" },
    },
  ],

  mesh: [
    {
      name: "Frame Mesh",
      templateId: "line-mesh",
      geometry: [1, 2, 3],
      params: { divisions: 8 },
    },
  ],

  design: [
    {
      name: "Steel Frame",
      templateId: "steel-member",
      geometry: [1, 2, 3],
    },
  ],
};

